import {
  MeshPhysicalNodeMaterial,
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import {
  uv,
  vec2,
  vec3,
  mix,
  smoothstep,
  texture,
  length,
} from 'three/tsl';
import { gsap } from 'gsap';

function hexToVec3(hex) {
  const h = hex.replace('#', '');
  const r = parseInt(h.substring(0, 2), 16) / 255;
  const g = parseInt(h.substring(2, 4), 16) / 255;
  const b = parseInt(h.substring(4, 6), 16) / 255;
  return vec3(r, g, b);
}

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const {
    Group,
    Mesh,
    BoxGeometry,
    PlaneGeometry,
    PointLight,
  } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  // --- Atlas-derived aspect ratio ---------------------------------------
  const atlasRect = { w: 512, h: 320 };
  const aspect = atlasRect.w / atlasRect.h;
  const cardHeight = 1.05;
  const cardWidth = cardHeight * aspect; // ~1.68
  const cardDepth = 0.07;

  const group = new Group();
  group.name = 'hub-collection-card-2';

  const content = new Group();
  group.add(content);

  // --- Engineered gradient + grain material -----------------------------
  const uvNode = uv();

  const inkColor = hexToVec3(colors.ink);
  const surfaceColor = hexToVec3(colors.surface);
  const accentColor = hexToVec3(colors.accent);

  const baseGradient = mix(surfaceColor, inkColor, uvNode.y);

  // thin accent trim line near top edge - keeps accent usage minimal
  const edgeMask = smoothstep(0.93, 0.965, uvNode.y).mul(
    smoothstep(0.05, 0.12, uvNode.x).mul(smoothstep(0.95, 0.88, uvNode.x))
  );
  const gradedColor = mix(baseGradient, accentColor, edgeMask.mul(0.45));

  const material = new MeshPhysicalNodeMaterial();
  material.colorNode = gradedColor;
  material.roughness = 0.56;
  material.metalness = 0.42;
  material.clearcoat = 0.18;
  material.clearcoatRoughness = 0.35;

  const geometry = new BoxGeometry(cardWidth, cardHeight, cardDepth);
  const cardMesh = new Mesh(geometry, material);
  content.add(cardMesh);

  // --- Grain texture (async swap once loaded) ----------------------------
  let grainTexture = null;
  ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((tex) => {
      grainTexture = tex;
      grainTexture.needsUpdate = true;

      const grainSample = texture(grainTexture, uvNode).r;
      const grainInfluence = mix(1.0, 0.86, grainSample);
      const grained = gradedColor.mul(grainInfluence);

      material.colorNode = grained;
      material.needsUpdate = true;
    })
    .catch(() => {
      /* grain is decorative only — silently keep flat gradient on failure */
    });

  // --- Rim / accent light (node-local, does not touch scene lights) -----
  const rimLight = new PointLight(colors.accent, 0.7, 4.0, 2.0);
  rimLight.position.set(cardWidth * 0.6, cardHeight * 0.5, 1.1);
  content.add(rimLight);

  // --- Contact shadow ------------------------------------------------------
  const shadowRadius = cardWidth * 0.7;
  const shadowGeo = new PlaneGeometry(shadowRadius * 2, shadowRadius * 2);
  const shadowUv = uv();
  const dist = length(shadowUv.sub(vec2(0.5, 0.5)));
  const shadowOpacity = smoothstep(0.5, 0.0, dist).mul(0.45);

  const shadowMaterial = new MeshBasicNodeMaterial();
  shadowMaterial.colorNode = hexToVec3(colors.surface);
  shadowMaterial.opacityNode = shadowOpacity;
  shadowMaterial.transparent = true;
  shadowMaterial.depthWrite = false;

  const shadowMesh = new Mesh(shadowGeo, shadowMaterial);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.set(0, -cardHeight / 2 - 0.02, cardDepth / 2 + 0.02);
  content.add(shadowMesh);

  // --- Entrance motion: weighted rise-in + settle ------------------------
  content.position.y = -0.4;
  content.scale.setScalar(0.97);

  const tl = gsap.timeline();
  tl.to(content.position, {
    y: 0,
    duration: 0.7,
    ease: 'power3.out',
  });
  tl.to(
    content.scale,
    {
      x: 1.04,
      y: 1.04,
      z: 1.04,
      duration: 0.35,
      ease: 'power2.out',
    },
    0.15
  );
  tl.to(
    content.scale,
    {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.9,
      ease: 'power4.out',
    },
    0.5
  );

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    tl.kill();

    geometry.dispose();
    material.dispose();
    shadowGeo.dispose();
    shadowMaterial.dispose();

    if (grainTexture) {
      grainTexture.dispose();
    }

    if (rimLight.dispose) rimLight.dispose();

    content.remove(cardMesh, rimLight, shadowMesh);
    group.remove(content);
  };

  return group;
}
